"use client";

import Link from "next/link";
import { ArrowLeft, Search, Copy, Check } from "lucide-react";
import { useState } from "react";

export default function SearchAPIPage() {
  const [copied, setCopied] = useState(false);

  const copyToClipboard = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      console.error("Failed to copy:", error);
    }
  };

  const examples = [
    {
      title: "Country search",
      code: `fetch('/ip-address-database/data/country.json')
  .then((res) => res.json())
  .then((data) => {
    const matches = data.countries.filter((country) =>
      country.code === 'US' || country.name.toLowerCase().includes('united')
    );
    console.log(matches);
  });`,
    },
    {
      title: "ASN search",
      code: `fetch('/ip-address-database/data/asn.json')
  .then((res) => res.json())
  .then((data) => {
    const matches = data.asns.filter((asn) => asn.asn === '12311');
    console.log(matches);
  });`,
    },
  ];

  return (
    <div className="space-y-6">
      <Link
        href="/docs"
        className="inline-flex items-center gap-2 text-[#6f8a7d] hover:text-[#c6d2ca] transition-colors font-mono text-sm"
      >
        <ArrowLeft size={16} />
        Back to Documentation
      </Link>

      <div className="space-y-3">
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono font-bold text-[#5c8aff] tracking-widest uppercase bg-[rgba(92,138,255,.08)] px-3 py-1 rounded-md border border-[rgba(92,138,255,.1)]">
            API Reference
          </span>
        </div>
        <h1 className="text-3xl md:text-4xl font-bold font-mono text-[#f2fff8]">
          Search API
        </h1>
        <p className="text-[#93a79d] font-mono text-lg max-w-2xl">
          The data is static, so search happens on the client or in your fetch
          logic by filtering the returned JSON.
        </p>
      </div>

      <div className="space-y-4">
        {examples.map((example) => (
          <div
            key={example.title}
            className="bg-[rgba(92,138,255,.03)] border border-[rgba(92,138,255,.08)] rounded-xl p-6"
          >
            <div className="flex items-center gap-2 mb-3">
              <Search size={16} className="text-[#5c8aff]" />
              <h2 className="text-lg font-mono font-bold text-[#f2fff8]">
                {example.title}
              </h2>
            </div>
            <div className="relative">
              <pre className="bg-[#0a100d] border border-[rgba(34,229,122,.06)] rounded-lg p-4 overflow-x-auto font-mono text-sm text-[#7fe9ab]">
                {example.code}
              </pre>
              <button
                onClick={() => copyToClipboard(example.code)}
                className="absolute top-3 right-3 p-1.5 rounded-md bg-[rgba(34,229,122,.06)] hover:bg-[rgba(34,229,122,.1)] transition-colors"
              >
                {copied ? (
                  <Check size={14} className="text-[#22e57a]" />
                ) : (
                  <Copy size={14} className="text-[#6f8a7d]" />
                )}
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
